    destruct(Hrec N)as(j&Hj&Hf). exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

Definition cbtrows_AST_141 : list (list (option Trans)) :=
  [r_AST_141_0000;
   r_AST_141_0001].

Lemma cbt_AST_141_covers : Forall coversTr (map row_to_tm cbtrows_AST_141).
Proof. exact (Forall_cons _ cv_AST_141_0000 (Forall_cons _ cv_AST_141_0001 (Forall_nil _))). Qed.
